entries[7449] = { ["name"] = "Muster: Schwärzliche Ledergamaschen", ["text"] = "Benötigt Lederverarbeitung (165)\nBenutzen: Lehrt Euch die Herstellung von schwärzlichen Ledergamaschen.\nSchwärzliche Ledergamaschen\nWird beim Anlegen gebunden\nBeine Leder\n86 Rüstung\n+13 Beweglichkeit\nHaltbarkeit 65 / 65\nBenötigt Stufe 28\nBenötigt Schweres Leder (10), Schwarzer Farbstoff , Feiner Faden (2)" }
entries[7450] = { ["name"] = "Muster: Grünwelpenrüstung", ["text"] = "Benötigt Lederverarbeitung (175)\nBenutzen: Lehrt Euch die Herstellung einer Grünwelpenrüstung.\nGrünwelpenrüstung\nWird beim Anlegen gebunden\nBrust Leder\n102 Rüstung\n+11 Willenskraft\nHaltbarkeit 85 / 85\nBenötigt Stufe 30\nAnlegen: Bei einem Treffer durch einen Nahkampfangreifer hat dieser Angreifer eine Chance von 5%, 10 Sek. lang in Schlaf versetzt zu werden. Wirkt nur bei Gegnern der Stufe 50 oder niedriger. (Procchance: 5%)\nBenötigt Grünwelpenschuppe (4), Schweres Leder (10), Feiner Faden (2)" }
entries[7451] = { ["name"] = "Muster: Grünwelpen-Armschienen", ["text"] = "Benötigt Lederverarbeitung (190)\nBenutzen: Lehrt Euch die Herstellung von Grünwelpenarmschienen.\nGrünwelpen-Armschienen\nWird beim Anlegen gebunden\nHandgelenke Leder\n47 Rüstung\n+8 Willenskraft\nHaltbarkeit 30 / 30\nBenötigt Stufe 33\nBenötigt Grünwelpenschuppe (6), Schweres Leder (8), Seidenfaden (2)" }
entries[7452] = { ["name"] = "Muster: Schwärzliche Stiefel", ["text"] = "Benötigt Lederverarbeitung (200)\nBenutzen: Lehrt Euch die Herstellung der schwärzlichen Stiefel.\nSchwärzliche Stiefel\nWird beim Anlegen gebunden\nFüße Leder\n76 Rüstung\n+11 Beweglichkeit\n+3 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Stufe 35\nBenötigt Schweres Leder (8), Schattenkatzenbalg (2), Schattenöl , Seidenfaden (2)" }
entries[7453] = { ["name"] = "Muster: Hurtige Stiefel", ["text"] = "Benötigt Lederverarbeitung (200)\nBenutzen: Lehrt Euch die Herstellung von hurtigen Stiefeln.\nHurtige Stiefel\nWird beim Anlegen gebunden\nFüße Leder\n76 Rüstung\n+10 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Stufe 35\nBenutzen: Erhöht das Lauftempo 15 Sek. lang um 40%. (1 Stunde Abklingzeit)\nBenötigt Schweres Leder (10), Hurtigkeitstrank (2), Dicke Spinnenseide (2), Seidenfaden" }
